use std::time::{Duration, Instant};

pub struct Bucket { cap: u32, tokens: f64, rate: f64, last: Instant }

impl Bucket {
    pub fn new(cap: u32, per_sec: f64) -> Self { Self { cap, tokens: cap as f64, rate: per_sec, last: Instant::now() } }
    pub fn try_take(&mut self, n: u32) -> bool {
        let now = Instant::now();
        self.tokens = (self.tokens + (now - self.last).as_secs_f64() * self.rate).min(self.cap as f64);
        self.last = now;
        if self.tokens >= n as f64 { self.tokens -= n as f64; true } else { false }
    }
}

